import { NextRequest, NextResponse } from "next/server";

// ============================================================
// SOUTHPRIDE SANCTUARY – ENQUIRY API ROUTE
// Forwards website enquiries server-side to Google Apps Script.
// The Apps Script saves the enquiry to Google Sheet "Sanctuary".
//
// Target Schema (9 Columns):
// A. Lead ID (Generated by Apps Script)
// B. Enquiry Date (Generated by Apps Script)
// C. Full Name (fullName)
// D. Mobile Number (mobileNumber)
// E. Email Address (emailAddress)
// F. Preferred Plot Size (preferredPlotSize)
// G. Budget Range (budgetRange)
// H. Enquiry Type (enquiryType)
// I. Questions or Specific Requirements (questionsOrRequirements)
// ============================================================

const GOOGLE_SHEETS_WEBHOOK_DEFAULT =
  "https://script.google.com/macros/s/AKfycbxzyuAF7pyuFiiIU9hAVekXEJt4ToScKvoMfjTwpcub9L4pi9XCPFwcUtz81qWOU4mwQQ/exec";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();

    const rawName = body.fullName || body.name || "";
    const rawMobile = body.mobileNumber || body.mobile || "";
    const rawEmail = body.emailAddress || body.email || "";
    const rawPlotSize = body.preferredPlotSize || body.plotSize || "";
    const rawBudget = body.budgetRange || body.budget || "";
    const rawEnquiryType = body.enquiryType || "Price Enquiry";
    const rawMessage = body.questionsOrRequirements || body.message || "";

    // 1. Server-side validation
    if (!rawName.trim()) {
      return NextResponse.json(
        { success: false, error: "Please enter your full name." },
        { status: 400 }
      );
    }

    if (!rawMobile.trim()) {
      return NextResponse.json(
        { success: false, error: "Please enter your mobile number." },
        { status: 400 }
      );
    }

    // Clean Indian 10-digit mobile number
    const mobileClean = rawMobile.replace(/\s+/g, "").replace(/^(\+91|91)/, "");
    if (!/^[6-9]\d{9}$/.test(mobileClean)) {
      return NextResponse.json(
        {
          success: false,
          error: "Please enter a valid 10-digit Indian mobile number (e.g. 9876543210).",
        },
        { status: 400 }
      );
    }

    // Validate email format if provided
    if (rawEmail.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rawEmail.trim())) {
      return NextResponse.json(
        { success: false, error: "Please enter a valid email address." },
        { status: 400 }
      );
    }

    // 2. Prepare payload matching Google Apps Script doPost(e) JSON structure
    const appsScriptPayload = {
      fullName: rawName.trim(),
      mobileNumber: mobileClean,
      emailAddress: rawEmail.trim(),
      preferredPlotSize: rawPlotSize.trim(),
      budgetRange: rawBudget.trim(),
      enquiryType: rawEnquiryType.trim(),
      questionsOrRequirements: rawMessage.trim(),

      // Backward compatibility keys
      name: rawName.trim(),
      mobile: mobileClean,
      email: rawEmail.trim(),
      plotSize: rawPlotSize.trim(),
      budget: rawBudget.trim(),
      message: rawMessage.trim(),
      source: body.source || "Website Enquiry Desk",
      timestamp: new Date().toISOString(),
    };

    // 3. Resolve server-side webhook URL
    const webhookUrl =
      process.env.GOOGLE_SCRIPT_URL ||
      process.env.GOOGLE_SHEETS_WEBHOOK_URL ||
      GOOGLE_SHEETS_WEBHOOK_DEFAULT;

    if (!webhookUrl) {
      console.error("Missing GOOGLE_SCRIPT_URL configuration.");
      return NextResponse.json(
        {
          success: false,
          error: "Server configuration error: GOOGLE_SCRIPT_URL is not set.",
        },
        { status: 500 }
      );
    }

    // 4. Forward to Google Apps Script
    try {
      const gasResponse = await fetch(webhookUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
        },
        body: JSON.stringify(appsScriptPayload),
        redirect: "follow",
      });

      const responseText = await gasResponse.text();
      let gasResult: { success?: boolean; message?: string; leadId?: string } | null = null;

      try {
        gasResult = JSON.parse(responseText);
      } catch {
        // Response may be HTML if Google redirected to sign-in (401)
      }

      // Check if Google Apps Script blocked request or returned failure
      if (
        gasResponse.status === 401 ||
        gasResponse.status === 403 ||
        (gasResult && gasResult.success === false) ||
        !gasResponse.ok
      ) {
        const errorDetail =
          gasResponse.status === 401
            ? "Google Apps Script 401 Unauthorized: The Web App deployment must have 'Who has access' set to 'Anyone'."
            : gasResult?.message ||
              "Google Sheets rejected the submission. Please verify sheet columns.";

        console.error("Google Apps Script Save Failed:", {
          status: gasResponse.status,
          error: errorDetail,
          rawResponse: responseText.slice(0, 300),
        });

        // Fail the request — DO NOT silently discard or claim success
        return NextResponse.json(
          {
            success: false,
            error: errorDetail,
          },
          { status: 502 }
        );
      }

      // 5. Successful confirmed save to Google Sheets
      const leadId = gasResult?.leadId || "SAN-CONFIRMED";
      console.log(`Lead confirmed in Google Sheets with ID: ${leadId}`);

      return NextResponse.json(
        {
          success: true,
          leadId,
          message: "Enquiry submitted successfully. Our sales team will contact you promptly.",
        },
        { status: 200 }
      );
    } catch (networkErr: any) {
      console.error("Network error communicating with Google Apps Script:", networkErr);
      return NextResponse.json(
        {
          success: false,
          error:
            "Could not connect to Google Sheets server. Please call or WhatsApp our sales desk directly.",
        },
        { status: 502 }
      );
    }
  } catch (err: any) {
    console.error("Enquiry API internal exception:", err);
    return NextResponse.json(
      {
        success: false,
        error: "Internal server error. Please call or WhatsApp our official sales desk.",
      },
      { status: 500 }
    );
  }
}
